flow-title:
import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var steps = [{ id: 'file', label: 'Файл' }, { id: 'fields', label: 'Поля', hint: 'Сопоставление' }, { id: 'check', label: 'Проверка' }];
var content = ['Выберите файл для импорта.', 'Сопоставьте столбцы файла с полями.', 'Проверьте данные перед импортом.'];
function App() {
    var a = React.useState(1), finished = React.useState(false);
    function select(index) { a[1](index); finished[1](false); }
    return <div className="dsstepper-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <S.DsStepper steps={steps} active={a[0]} onSelect={finished[0] ? undefined : select} isComplete={finished[0]} ariaLabel={'Импорт объектов'}/>
    <p role={'status'}>
    {finished[0] ? 'Импорт завершён.' : content[a[0]]}
    </p>
    <div className={'actions'}>
    <S.DsButton tone={'secondary'} disabled={a[0] === 0 || finished[0]} onClick={function () { select(a[0] - 1); }}>
    {'Назад'}
    </S.DsButton>
    <S.DsButton disabled={finished[0]} onClick={function () {
            if (a[0] < steps.length - 1)
                select(a[0] + 1);
            else
                finished[1](true);
        }}>
    {a[0] === steps.length - 1 ? 'Импортировать' : 'Далее'}
    </S.DsButton>
    <S.DsButton tone={'ghost'} onClick={function () { select(0); }}>
    {'Начать заново'}
    </S.DsButton>
    </div>
    </div>
    </div>;
}

const exampleStyles = ".dsstepper-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsstepper-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsstepper-example p{margin:0}\n.dsstepper-example .actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center}";

export { App as Example };

