import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var steps = [{ id: 'file', label: 'Файл' }, { id: 'fields', label: 'Поля', hint: 'Сопоставление' }, { id: 'check', label: 'Проверка' }];
function App() {
    var revisited = React.useState(2);
    return <div className="dsstepper-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <S.DsStepper steps={[{ id: 'file', label: 'Файл', disabled: true }, steps[1], steps[2]]} active={revisited[0]} completed={[0, 1]} onSelect={revisited[1]} ariaLabel={'Настройка импорта'}/>
    <p>
    {'Файл уже подтверждён, вернуться к нему нельзя. Шаг «Поля» можно открыть повторно; завершённость сохраняется.'}
    </p>
    <S.DsButton tone={'secondary'} disabled={revisited[0] === 2} onClick={function () { revisited[1](2); }}>
    {'К проверке'}
    </S.DsButton>
    </div>
    </div>;
}

const exampleStyles = ".dsstepper-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsstepper-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsstepper-example p{margin:0}\n";

